/** Links between pages, for a Link header or a JSON response body. */

import type { OffsetPage, PageLinks } from "./types.ts";

function href(basePath: string, page: number, perPage: number): string {
  const separator = basePath.includes("?") ? "&" : "?";
  return `${basePath}${separator}page=${page}&per_page=${perPage}`;
}

/** The links of a page: first, previous, next, and last. */
export function pageLinks(basePath: string, result: OffsetPage<unknown>): PageLinks {
  const { page, perPage, totalPages } = result;
  return {
    first: href(basePath, 1, perPage),
    prev: result.hasPrev ? href(basePath, page - 1, perPage) : null,
    next: result.hasNext ? href(basePath, page + 1, perPage) : null,
    last: href(basePath, totalPages, perPage),
  };
}

/** The same links as the value of an HTTP Link header. */
export function linkHeader(basePath: string, result: OffsetPage<unknown>): string {
  const links = pageLinks(basePath, result);
  const parts: string[] = [];
  for (const rel of ["first", "prev", "next", "last"] as const) {
    const target = links[rel];
    if (target !== null) {
      parts.push(`<${target}>; rel="${rel}"`);
    }
  }
  return parts.join(", ");
}

/** Page-number pagination. */

import { resolveSize } from "./limits.ts";
import type { OffsetOptions, OffsetPage } from "./types.ts";

/** Cut one page out of a list. Pages past the end are empty, not an error. */
export function paginate<T>(items: readonly T[], options: OffsetOptions = {}): OffsetPage<T> {
  const page = options.page ?? 1;
  if (!Number.isInteger(page) || page < 1) {
    throw new RangeError(`page must be a whole number of at least 1, got ${page}`);
  }
  const perPage = resolveSize(options.perPage);
  const total = items.length;
  const totalPages = Math.max(1, Math.ceil(total / perPage));
  const start = (page - 1) * perPage;
  return {
    items: items.slice(start, start + perPage),
    page,
    perPage,
    total,
    totalPages,
    hasNext: page < totalPages,
    hasPrev: page > 1,
  };
}

/** Shared types for the pagination helpers. */

/** Query parameters as a web framework hands them over: every value is a string. */
export type Query = Readonly<Record<string, string | undefined>>;

/** Options of `paginate`. */
export interface OffsetOptions {
  /** 1-based page number; 1 by default. */
  page?: number;
  /** Items per page; see `resolveSize` for the default and the limit. */
  perPage?: number;
}

/** One page of a list, as `paginate` returns it. */
export interface OffsetPage<T> {
  items: T[];
  page: number;
  perPage: number;
  /** Number of items in the whole list. */
  total: number;
  /** Number of pages; an empty list has one (empty) page. */
  totalPages: number;
  hasNext: boolean;
  hasPrev: boolean;
}

/** The page request that `parsePageParams` reads from a query. */
export interface PageParams {
  page: number;
  perPage: number;
}

/** Links to related pages; `prev` and `next` are null at the ends. */
export interface PageLinks {
  first: string;
  prev: string | null;
  next: string | null;
  last: string;
}
